import os
from azure.ai.contentsafety import ContentSafetyClient
from azure.core.credentials import AzureKeyCredential
from azure.ai.contentsafety.models import AnalyzeTextOptions, TextCategory

def moderate_messages(messages):
    endpoint = os.environ["AZURE_CONTENT_SAFETY_ENDPOINT"]
    key = os.environ["AZURE_CONTENT_SAFETY_KEY"]

    client = ContentSafetyClient(endpoint, AzureKeyCredential(key))
    results = []

    for message in messages:
        request = AnalyzeTextOptions(text=message)
        response = client.analyze_text(request)

        decision = {
            "message": message,
            "block": any(
                result.severity >= 4
                for result in response.categories_analysis
            ),
            "categories": {
                category: result.severity
                for category, result in zip(
                    [TextCategory.HATE, TextCategory.SELF_HARM, TextCategory.SEXUAL, TextCategory.VIOLENCE],
                    response.categories_analysis
                )
            }
        }
        results.append(decision)

    return results
